#include <iostream>
#include <sstream>
#include <type_traits>

int main() {
    // Verify inheritance relations at compile time
    static_assert(std::is_base_of_v<std::basic_ios<char>, std::istream>,
                  "istream must inherit from basic_ios");
    static_assert(std::is_base_of_v<std::ostream, std::iostream>,
                  "iostream must inherit from ostream");

    int grade = 95;
    // Stream insertion flows right-to-left into stream
    std::cout << "Grade value: " << grade << '\n';

    // Demonstrate stringstream buffering hierarchy
    std::ostringstream oss;
    oss << "Buffered log for grade: " << grade;
    std::cout << oss.str() << '\n';

    return 0;
}

#include <iostream>

int main() {
    const char* const word = "again";

    // 1. Output string content
    std::cout << "Value of word is: " << word << '\n';

    // 2. Check that void* cast yields a non-null pointer
    const void* addr = static_cast<const void*>(word);
    std::cout << "Address is non-null: " << (addr != nullptr ? "true" : "false") << '\n';

    // 3. Cascaded put calls (character literal and ASCII integer)
    std::cout.put('A').put(65).put('\n'); // outputs 'A', 'A', and newline

    return 0;
}

#include <iostream>
#include <sstream>

int main() {
    // Simulate input buffer with mixed characters and whitespace
    std::istringstream stream("Hi 7\nEnd");

    int ch;
    std::cout << "Stream reading raw characters:\n";
    while ((ch = stream.get()) != EOF) {
        if (ch == '\n') {
            std::cout << "[NEWLINE]\n";
        } else {
            std::cout.put(static_cast<char>(ch));
        }
    }

    std::cout << "\nAt EOF? " << (stream.eof() ? "true" : "false") << '\n';
    return 0;
}
